using System.Collections;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.InputSystem;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
[DefaultExecutionOrder(-200)]public sealed class PortableTablet:MonoBehaviour {
 public PlayerMovement player;public Camera view;public GameObject modelPrefab;
 public Vector3 position=new Vector3(0,-.035f,.76f),rotation=new Vector3(2,0,0);public float scale=1,animationDuration=.42f;
 public bool IsOpen{get;private set;}public bool Animating{get;private set;}public GridShiftNativeOperations Operations{get;private set;}
 GameObject model,hiddenGeometry;bool geometryWasActive;int bodyMask;CanvasGroup screen;bool blocked,visible;CursorLockMode cursor;CanvasGroup[] hud;float[] alpha;Coroutine transition;
 void Awake(){if(player==null)player=GetComponent<PlayerMovement>();if(view==null&&player!=null)view=player.CameraTransform.GetComponent<Camera>();}
 void Update(){if(Keyboard.current==null)return;if(IsOpen){if(GridShiftControls.InterfaceBack(Operations!=null&&Operations.TextEditing)||(GridShiftControls.Down(GSAction.Tablet)&&(Operations==null||!Operations.TextEditing))){EscapeInput.Consume();GridShiftControls.SuppressFrame();Close();}return;}if(GridShiftControls.Down(GSAction.Tablet))Open();}
 public bool Open(){if(IsOpen||Animating||player==null||view==null||player.ControlsBlocked||Time.timeScale<=0||SceneManager.GetActiveScene()!=gameObject.scene||(PauseMenu.Instance!=null&&PauseMenu.Instance.IsOpen)||(WorldSession.Instance!=null&&WorldSession.Instance.Busy))return false;
 if(model==null){model=Instantiate(modelPrefab,view.transform,false);model.name="PortableTabletViewModel";screen=model.GetComponentInChildren<CanvasGroup>(true);var canvas=screen.GetComponent<Canvas>();canvas.worldCamera=view;if(canvas.GetComponent<GraphicRaycaster>()==null)canvas.gameObject.AddComponent<GraphicRaycaster>();Operations=new GameObject("UrbanFlowNative",typeof(RectTransform)).AddComponent<GridShiftNativeOperations>();Operations.Initialize(screen.transform,view);}
 blocked=player.ControlsBlocked;cursor=Cursor.lockState;visible=Cursor.visible;player.BlockControls(true);Cursor.lockState=CursorLockMode.None;Cursor.visible=true;IsOpen=true;GridShiftAudio.Play("Tablet_Open","UI",.5f);DeliveryManager.Instance?.Company.Missions.TabletOpened();model.SetActive(true);screen.alpha=0;screen.blocksRaycasts=screen.interactable=true;
 bodyMask=view.cullingMask;view.cullingMask&=~((1<<7)|(1<<8));hiddenGeometry=player.CameraTransform.Find("Hud")?.gameObject;if(hiddenGeometry!=null){geometryWasActive=hiddenGeometry.activeSelf;hiddenGeometry.SetActive(false);}var groups=new System.Collections.Generic.List<CanvasGroup>();foreach(var c in player.GetComponentsInChildren<Canvas>(true))if(!c.transform.IsChildOf(model.transform)){var g=c.GetComponent<CanvasGroup>();if(g==null)g=c.gameObject.AddComponent<CanvasGroup>();groups.Add(g);}hud=groups.ToArray();alpha=new float[hud.Length];for(int i=0;i<hud.Length;i++){alpha[i]=hud[i].alpha;hud[i].alpha=0;}transition=StartCoroutine(Animate(true));return true;}
 public void Close(){if(!IsOpen||Animating)return;GridShiftAudio.Play("Tablet_Close","UI",.4f);Operations.Hide();transition=StartCoroutine(Animate(false));}
 IEnumerator Animate(bool enter){Animating=true;var below=position+new Vector3(0,-.85f,.08f);for(float t=0;t<Mathf.Max(.05f,animationDuration);t+=Time.unscaledDeltaTime){float k=Mathf.SmoothStep(0,1,t/Mathf.Max(.05f,animationDuration));model.transform.localPosition=Vector3.Lerp(enter?below:position,enter?position:below,k);model.transform.localRotation=Quaternion.Euler(rotation+new Vector3(Mathf.Lerp(enter?14:0,enter?0:14,k),0,0));model.transform.localScale=Vector3.one*scale;screen.alpha=enter?Mathf.InverseLerp(.55f,1,k):1-k;yield return null;}Animating=false;transition=null;if(enter){model.transform.localPosition=position;model.transform.localRotation=Quaternion.Euler(rotation);screen.alpha=1;Operations.Open();}else Restore();}
 void Restore(){if(Operations!=null)Operations.Hide();if(screen!=null){screen.alpha=0;screen.blocksRaycasts=screen.interactable=false;}if(model!=null)model.SetActive(false);if(hud!=null)for(int i=0;i<hud.Length;i++)if(hud[i]!=null)hud[i].alpha=alpha[i];if(view!=null)view.cullingMask=bodyMask;if(hiddenGeometry!=null){hiddenGeometry.SetActive(geometryWasActive);hiddenGeometry=null;}if(player!=null)player.BlockControls(blocked);Cursor.lockState=cursor;Cursor.visible=visible;IsOpen=Animating=false;}
 void OnDisable(){if(transition!=null)StopCoroutine(transition);if(IsOpen)Restore();}void OnDestroy(){if(model!=null)Destroy(model);}
}

